const { v4: uuidv4 } = require('uuid');
const {
  Settings,
  Workflows,
  WorkflowRuns,
  Submissions,
  InternalNumbers,
} = require('../models');

/**
 * Parse Drawflow export into a simple adjacency graph.
 */
function parseDrawflowGraph(graph) {
  const data = graph?.drawflow?.Home?.data || {};
  const nodes = {};

  for (const [id, node] of Object.entries(data)) {
    const outputs = {};
    const outKeys = Object.keys(node.outputs || {});
    outKeys.forEach((key, index) => {
      const connections = (node.outputs[key]?.connections || []).map((c) => String(c.node));
      outputs[key] = connections;
      // Also expose by index for Yes/No (output_1 = true, output_2 = false)
      outputs[`_${index}`] = connections;
    });

    nodes[String(id)] = {
      id: String(id),
      type: node.name,
      data: node.data || {},
      outputs,
      pos: { x: node.pos_x, y: node.pos_y },
    };
  }

  return nodes;
}

function findTriggerNodes(nodes, messageBody) {
  const normalized = String(messageBody || '').trim().toLowerCase();
  return Object.values(nodes).filter((n) => {
    if (n.type !== 'trigger_message') return false;
    const keywords = String(n.data.keywords || 'hi')
      .split(',')
      .map((k) => k.trim().toLowerCase())
      .filter(Boolean);
    return keywords.some((k) => normalized === k || normalized.startsWith(k));
  });
}

function nextNodes(node, outputKey = 'output_1') {
  if (!node) return [];
  const list = node.outputs[outputKey] || node.outputs._0 || [];
  return list;
}

function renderTemplate(template, vars) {
  return String(template || '').replace(/\{\{(\w+)\}\}/g, (_, key) => {
    return vars[key] != null ? String(vars[key]) : '';
  });
}

function getBaseUrl() {
  return (process.env.BASE_URL || 'http://localhost:3000').replace(/\/$/, '');
}

class WorkflowEngine {
  /**
   * @param {{ sendMessage: (phone: string, body: string) => Promise<any> }} whatsapp
   */
  constructor(whatsapp) {
    this.whatsapp = whatsapp;
  }

  getActiveGraph() {
    const workflow = Workflows.getActive();
    if (!workflow) return null;
    return { workflow, nodes: parseDrawflowGraph(workflow.graph) };
  }

  /**
   * Entry: inbound WhatsApp text.
   */
  async handleIncomingMessage({ phone, body }) {
    const active = this.getActiveGraph();
    if (!active) {
      return { handled: false, reason: 'no_active_workflow' };
    }

    // Resume Yes/No waiters first
    const waiting = WorkflowRuns.findWaiting(phone, 'yes_no');
    if (waiting) {
      return this.resumeYesNo(waiting, body, active.nodes);
    }

    const triggers = findTriggerNodes(active.nodes, body);
    if (!triggers.length) {
      return { handled: false, reason: 'no_matching_trigger' };
    }

    const open = Submissions.findLatestOpen(phone);
    if (open && open.status === 'awaiting_confirmation') {
      await this.whatsapp.sendMessage(
        phone,
        Settings.get('already_pending_message') ||
          'You already have a pending request. Reply Yes / No to confirm.'
      );
      return { handled: true, reason: 'already_pending' };
    }

    const run = WorkflowRuns.create({
      workflow_id: active.workflow.id,
      customer_phone: phone,
      context: { phone, message: body },
    });

    const startId = triggers[0].id;
    return this.executeFrom(run.id, startId, active.nodes, { phone });
  }

  /**
   * Entry: web form submitted.
   */
  async handleFormSubmit(submission) {
    const active = this.getActiveGraph();
    if (!active) return { handled: false };

    let waiting = null;
    if (submission.workflow_run_id) {
      waiting = WorkflowRuns.get(submission.workflow_run_id);
    }
    if (!waiting || waiting.waiting_for !== 'form_submit') {
      waiting = WorkflowRuns.findWaitingByToken(submission.token, 'form_submit');
    }
    if (!waiting) {
      // Fallback: legacy path without a run — still send confirmation via settings
      return { handled: false, reason: 'no_waiting_run' };
    }

    const ctx = {
      ...waiting.context,
      name: submission.customer_name,
      insurance_type: submission.insurance_type,
      company: submission.company,
      phone: submission.customer_phone,
      form_submitted_at: submission.form_submitted_at,
      submission_token: submission.token,
    };

    WorkflowRuns.update(waiting.id, {
      status: 'running',
      waiting_for: null,
      context: ctx,
      submission_token: submission.token,
    });

    const nodeId = waiting.current_node_id;
    const node = active.nodes[nodeId];
    if (!node) return { handled: false };

    // form_submit node: send confirmation then continue to next (usually condition)
    const confirmation = renderTemplate(
      node.data.confirmation_message || Settings.get('confirmation_template'),
      ctx
    );
    if (confirmation) {
      await this.whatsapp.sendMessage(submission.customer_phone, confirmation);
    }

    const outs = nextNodes(node, 'output_1');
    if (!outs.length) {
      WorkflowRuns.update(waiting.id, { status: 'completed', waiting_for: null });
      return { handled: true };
    }

    return this.executeFrom(waiting.id, outs[0], active.nodes, ctx);
  }

  async resumeYesNo(runRow, body, nodes) {
    const run = WorkflowRuns.get(runRow.id);
    const node = nodes[run.current_node_id];
    if (!node || node.type !== 'condition_yes_no') {
      return { handled: false };
    }

    const lower = String(body || '').trim().toLowerCase();
    const yesKeys = String(node.data.yes_keywords || 'yes,y,confirm,ok,okay')
      .split(',')
      .map((k) => k.trim().toLowerCase());
    const noKeys = String(node.data.no_keywords || 'no,n,cancel')
      .split(',')
      .map((k) => k.trim().toLowerCase());

    let branch = null;
    if (yesKeys.includes(lower)) branch = 'output_1';
    else if (noKeys.includes(lower)) branch = 'output_2';
    else return { handled: false, reason: 'unmatched_reply' };

    const ctx = { ...run.context, reply: body, branch };
    WorkflowRuns.update(run.id, {
      status: 'running',
      waiting_for: null,
      context: ctx,
    });

    if (run.submission_token) {
      const sub = Submissions.getByToken(run.submission_token);
      if (sub) {
        if (branch === 'output_1') Submissions.markConfirmed(sub.id);
        else Submissions.markCancelled(sub.id);
      }
    }

    const outs = nextNodes(node, branch);
    if (!outs.length) {
      WorkflowRuns.update(run.id, { status: 'completed', waiting_for: null });
      return { handled: true };
    }
    return this.executeFrom(run.id, outs[0], nodes, ctx);
  }

  async executeFrom(runId, nodeId, nodes, ctx = {}) {
    let currentId = String(nodeId);
    const visited = new Set();
    const maxSteps = 40;

    for (let step = 0; step < maxSteps; step++) {
      if (!currentId || visited.has(currentId)) break;
      visited.add(currentId);

      const node = nodes[currentId];
      if (!node) {
        WorkflowRuns.update(runId, {
          status: 'failed',
          last_error: `Missing node ${currentId}`,
          waiting_for: null,
        });
        return { handled: false, error: 'missing_node' };
      }

      WorkflowRuns.update(runId, {
        status: 'running',
        current_node_id: currentId,
        waiting_for: null,
        context: ctx,
      });

      const result = await this.executeNode(runId, node, ctx);

      if (result.wait) {
        WorkflowRuns.update(runId, {
          status: 'waiting',
          current_node_id: currentId,
          waiting_for: result.wait,
          context: result.context || ctx,
          submission_token: result.submission_token || undefined,
        });
        return { handled: true, waiting: result.wait, runId };
      }

      if (result.context) ctx = result.context;

      if (result.stop) {
        WorkflowRuns.update(runId, {
          status: result.status || 'completed',
          waiting_for: null,
          context: ctx,
        });
        return { handled: true, runId };
      }

      const outKey = result.output || 'output_1';
      const next = nextNodes(node, outKey);
      if (!next.length) {
        WorkflowRuns.update(runId, { status: 'completed', waiting_for: null, context: ctx });
        return { handled: true, runId };
      }
      currentId = next[0];
    }

    WorkflowRuns.update(runId, {
      status: 'failed',
      last_error: 'Max steps exceeded',
      waiting_for: null,
    });
    return { handled: false, error: 'max_steps' };
  }

  async executeNode(runId, node, ctx) {
    switch (node.type) {
      case 'trigger_message':
        return { output: 'output_1' };

      case 'send_form_link': {
        const phone = ctx.phone;
        let submission = Submissions.findLatestOpen(phone);
        if (!submission || submission.status !== 'awaiting_form') {
          submission = Submissions.create({
            token: uuidv4(),
            customer_phone: phone,
            workflow_run_id: runId,
          });
        } else {
          Submissions.setWorkflowRun(submission.token, runId);
        }

        const formLink = `${getBaseUrl()}/form/${submission.token}`;
        const vars = {
          ...ctx,
          business_name: Settings.get('business_name', 'Insurance'),
          form_link: formLink,
          phone,
        };
        const text = renderTemplate(
          node.data.message ||
            'Please fill out this form:\n{{form_link}}',
          vars
        );
        await this.whatsapp.sendMessage(phone, text);

        return {
          output: 'output_1',
          context: { ...ctx, ...vars, submission_token: submission.token },
          submission_token: submission.token,
        };
      }

      case 'form_submit':
        // Pause until HTTP form POST resumes this run
        return {
          wait: 'form_submit',
          submission_token: ctx.submission_token,
          context: ctx,
        };

      case 'condition_yes_no':
        return { wait: 'yes_no', context: ctx };

      case 'forward_desk': {
        const phone = ctx.phone;
        const submission = ctx.submission_token
          ? Submissions.getByToken(ctx.submission_token)
          : null;

        const target = InternalNumbers.resolveForType(
          ctx.insurance_type || submission?.insurance_type
        );

        if (!target) {
          await this.whatsapp.sendMessage(
            phone,
            'Your details are confirmed, but no internal desk number is configured yet.'
          );
          return { stop: true, status: 'completed', context: ctx };
        }

        const forwardText = renderTemplate(
          Settings.get('forward_template') ||
            '📋 *New Insurance Lead*\n\n• Name: {{name}}\n• Phone: {{phone}}\n• Type: {{insurance_type}}\n• Company: {{company}}',
          {
            name: ctx.name || submission?.customer_name,
            phone,
            insurance_type: ctx.insurance_type || submission?.insurance_type,
            company: ctx.company || submission?.company,
            submitted_at: ctx.form_submitted_at || submission?.form_submitted_at,
          }
        );

        await this.whatsapp.sendMessage(target.phone, forwardText);

        if (submission) {
          Submissions.markForwarded(submission.id, target.phone);
        }

        const success = renderTemplate(
          node.data.success_message || Settings.get('success_message'),
          ctx
        );
        if (success) {
          await this.whatsapp.sendMessage(phone, success);
        }

        return { output: 'output_1', context: { ...ctx, forwarded_to: target.phone } };
      }

      case 'send_text': {
        const text = renderTemplate(node.data.message || '', {
          ...ctx,
          business_name: Settings.get('business_name', 'Insurance'),
        });
        if (text) {
          await this.whatsapp.sendMessage(ctx.phone, text);
        }
        return { output: 'output_1', context: ctx };
      }

      default:
        console.warn('[Workflow] Unknown node type:', node.type);
        return { output: 'output_1' };
    }
  }
}

module.exports = { WorkflowEngine, parseDrawflowGraph, renderTemplate };
